COMMON = '''Use case: stylized-concept. Asset type: one transparent knee-up companion portrait for a Korean Age-of-Sail exploration RPG. Create ONE original fictional woman who is CLEARLY A MATURE ADULT AGE 30 TO 38, with adult facial structure, not a teenager or a child. The provided images are selected adult-looking appearance references only; do not copy identity, modern clothes or scenery. DESIGN: {design} BODY: naturally curvy adult with a visibly large full bust, proportional anatomy, securely dressed in fully opaque cloth. The user requests attractive nonconservative TRADITIONAL ETHNIC CLOTHING, so use the specified community's garment structure, weaving, embroidery and jewellery. Let the open neckline, bare shoulders/arms or waist arise from regional garment draping; do not turn every costume into a Western corset or bra-and-miniskirt. This is a tasteful game adaptation of traditional clothing, not a claim of exact historical reconstruction. Confident neutral standing pose with natural relaxed hands, focus on character personality. STYLE: refined semi-realistic hand-painted digital oil illustration consistent with premium historical game portraits, mature expressive face, subtle painted skin, detailed fabric and jewellery, soft directional warm light with neutral fill. COMPOSITION: vertical 2:3, 1024x1536. Entire head and hair with margin, hands and elbows inside frame. Show head through BOTH KNEES, crop immediately below knees, no feet, boots or shins. ONE character only, no face inset or panels. GENUINELY TRANSPARENT ALPHA BACKGROUND, no scenery, gradient, opaque background, halo, glow or shadow plane. No text, border, logo, watermark, nudity or erotic pose. Dark brown eyes. Preserve clear distinct facial identity and hairstyle for this community; avoid repeating the same face across the set.'''

def main():
    dest = ROOT / 'tools/folk_asia_pacific_women_20261107_prompts.json'
    if dest.exists():
        print('기존 제작 명세 보존')
        return
    rows = []
    for id_, name, region, numbers, design in ROWS:
        assert not set(numbers).intersection(EXCLUDED)
        rows.append(dict(id=id_, name=name, region=region, reference_numbers=numbers,
            refs=['C:/Users/User/AppData/Local/Temp/codex-clipboard-' + REFS[n-1] + '.png' for n in numbers],
            design=design, prompt=COMMON.format(design=design), face_key='portraits/folk-join/' + id_ + '_f_20261107_v1'))
    spec = dict(date='2026-11-07', mode='built-in image_gen', scope='새 중국 10·동남아 4·폴리네시아 4종과 기존 마오리·하와이 2종: 여성 20종, 얼굴상·무릎상 40장.',
        excluded_reference_numbers=EXCLUDED, portraits=rows, costume_sources=[
            'https://www.metmuseum.org/art/collection/search/85275',
            'https://www.metmuseum.org/art/collection/search/70360',
            'https://collections.tepapa.govt.nz/topic/1954',
            'https://collections.tepapa.govt.nz/object/1346071',
            'https://collections.tepapa.govt.nz/topic/1956',
            'https://www.tepapa.govt.nz/digital-museum/explore-digital-museum/maori/maori-weaving',
            'https://vwu.vn/chi-tiet-anh?_TTHTThuVienAnhShow_WAR_ECOITThuVienAnhportlet_INSTANCE_ehGsBSsh8Uou_categoryDetailId=4812145'])
    dest.write_text(json.dumps(spec, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
    print('여성 원화 지시문', len(rows))

if __name__ == '__main__':
    main()
